CREATE TABLE IF NOT EXISTS "a_public__admin_student_provisioning_operations" (
 "id" TEXT NOT NULL,
 "operation_id" TEXT NOT NULL,
 "request_fingerprint" TEXT NOT NULL,
 "mode" TEXT NOT NULL,
 "status" TEXT NOT NULL,
 "current_step" TEXT NOT NULL,
 "order_code" TEXT,
 "safe_result" TEXT NOT NULL,
 "actor_id" TEXT,
 "lease_token" TEXT,
 "lease_expires_at" TEXT,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 "email_dispatch_state" TEXT,
 "email_dispatch_attempt" INTEGER NOT NULL,
 "email_dispatch_idempotency_key" TEXT,
 "email_provider_message_id" TEXT,
 "email_dispatch_started_at" TEXT,
 "email_dispatch_finished_at" TEXT,
 PRIMARY KEY("id"),
 CHECK(((lease_token IS NULL) = (lease_expires_at IS NULL))),
 CHECK(((email_dispatch_attempt >= 0) AND (email_dispatch_attempt <= 100))),
 CHECK((((email_dispatch_state IS NULL) AND (email_dispatch_attempt = 0) AND (email_dispatch_idempotency_key IS NULL)) OR ((email_dispatch_state IS NOT NULL) AND (email_dispatch_attempt >= 1) AND (email_dispatch_idempotency_key IS NOT NULL) AND ((substr(email_dispatch_idempotency_key,1) NOT GLOB '*[^A-Za-z0-9/._:-]*' AND length(substr(email_dispatch_idempotency_key,1))>=8 AND length(substr(email_dispatch_idempotency_key,1))<=200))))),
 CHECK(((email_dispatch_state IS NULL) OR (email_dispatch_state IN ('started', 'sent', 'manual_review', 'retry_authorized')))),
 CHECK(((email_provider_message_id IS NULL) OR (((length(email_provider_message_id) >= 1) AND (length(email_provider_message_id) <= 160)) AND ((substr(email_provider_message_id,1) NOT GLOB '*[^A-Za-z0-9._:-]*' AND length(substr(email_provider_message_id,1))>=1))))),
 CHECK((mode IN ('paid', 'free', 'trial'))),
 CHECK((json_type(safe_result) = 'object')),
 CHECK((status IN ('running', 'partial', 'completed', 'failed')))
);
