 FOREIGN KEY(lesson_task_id) REFERENCES "a_public__lesson_tasks"(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 CHECK((((status = 'completed') AND (completed_at IS NOT NULL) AND (skipped_at IS NULL)) OR ((status = 'skipped') AND (skipped_at IS NOT NULL) AND (completed_at IS NULL)))),
 CHECK((status IN ('completed', 'skipped')))
);
CREATE TABLE IF NOT EXISTS "a_public__support_bookings" (
 "id" TEXT NOT NULL,
 "customer_name" TEXT NOT NULL,
 "email" TEXT NOT NULL,
 "phone" TEXT NOT NULL,
 "topic" TEXT NOT NULL,
 "note" TEXT NOT NULL,
 "appointment_date" TEXT NOT NULL,
 "appointment_time" TEXT NOT NULL,
 "starts_at" TEXT NOT NULL,
 "ends_at" TEXT NOT NULL,
 "status" TEXT NOT NULL,
 "hold_expires_at" TEXT NOT NULL,
 "amount" INTEGER NOT NULL,
 "order_id" TEXT,
 "order_code" TEXT,
 "paid_at" TEXT,
 "telegram_sent_at" TEXT,
 "telegram_last_error" TEXT,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 "duration_minutes" INTEGER NOT NULL,
 "booking_type" TEXT NOT NULL,
 PRIMARY KEY("id"),
 FOREIGN KEY(order_id) REFERENCES "a_public__orders"(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
 CHECK((((amount = 500000) AND ((booking_type = 'student') OR ((booking_type = 'consultation') AND (duration_minutes >= 60)))) OR (((booking_type = 'student') AND (((duration_minutes = 30) AND (amount IN ((500000), (1000000)))) OR ((duration_minutes > 30) AND (amount = (1000000 + (((duration_minutes - 30) / 30) * 500000)))))) OR ((booking_type = 'consultation') AND (duration_minutes >= 60) AND (amount = (2000000 + (((duration_minutes - 60) / 30) * 700000))))))),
 CHECK(((length(note) >= 0) AND (length(note) <= 2000))),
 CHECK((status IN ('held', 'confirmed', 'needs_review', 'cancelled'))),
 CHECK((booking_type IN ('student', 'consultation')))
);
CREATE TABLE IF NOT EXISTS "a_public__support_busy_dates" (
 "busy_date" TEXT NOT NULL,
 "note" TEXT,
 "created_by" TEXT,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 PRIMARY KEY("busy_date")
);
CREATE TABLE IF NOT EXISTS "a_public__telegram_business_report_runs" (
 "id" TEXT NOT NULL,
 "run_key" TEXT NOT NULL,
 "slot" TEXT NOT NULL,
 "window_start" TEXT NOT NULL,
 "window_end" TEXT NOT NULL,
 "state" TEXT NOT NULL,
 "attempt_count" INTEGER NOT NULL,
 "lease_token" TEXT,
 "lease_expires_at" TEXT,
 "last_error" TEXT,
 "started_at" TEXT,
 "sent_at" TEXT,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 PRIMARY KEY("id"),
 CHECK(((lease_token IS NULL) = (lease_expires_at IS NULL))),
 CHECK(((attempt_count >= 0) AND (attempt_count <= 100))),
 CHECK((window_end > window_start)),
 CHECK((length(COALESCE(last_error, '')) <= 800)),
 CHECK(((length(run_key) >= 20) AND (length(run_key) <= 180))),
 CHECK((slot IN ('morning', 'full-day'))),
 CHECK((state IN ('processing', 'sent', 'failed')))
);
CREATE TABLE IF NOT EXISTS "a_public__telegram_meta_campaign_hourly_snapshots" (
 "id" TEXT NOT NULL,
 "ad_account_id" TEXT NOT NULL,
 "entity_level" TEXT NOT NULL,
 "entity_id" TEXT NOT NULL,
 "entity_name" TEXT NOT NULL,
 "local_start_at" TEXT NOT NULL,
 "local_end_at" TEXT NOT NULL,
 "spend" TEXT NOT NULL,
 "data_status" TEXT NOT NULL,
 "source" TEXT NOT NULL,
 "fetched_at" TEXT NOT NULL,
 "created_at" TEXT NOT NULL,
 "updated_at" TEXT NOT NULL,
 "impressions" INTEGER NOT NULL,
 "clicks" INTEGER NOT NULL,
 "purchases" TEXT NOT NULL,
 "purchase_value" TEXT NOT NULL,
 PRIMARY KEY("id"),
 CHECK((clicks >= 0)),
 CHECK((data_status IN ('final', 'partial', 'missing'))),
 CHECK((entity_level IN ('account', 'campaign'))),
 CHECK((impressions >= 0)),
 CHECK((purchase_value >= (0))),
 CHECK((purchases >= (0))),
 CHECK((source = 'facebook_ads_mcp')),
 CHECK((spend >= (0)))
);
CREATE TABLE IF NOT EXISTS "a_public__testimonials" (
 "id" TEXT NOT NULL,
 "student_name" TEXT NOT NULL,
 "content" TEXT,
 "avatar" TEXT,
 "rating" INTEGER,
 "created_at" TEXT,
 PRIMARY KEY("id")
);
